<?php
require __DIR__.'/../includes/functions.php';require_staff();$error=null;
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$action=$_POST['action']??'';$id=(int)($_POST['id']??0);if($action==='create'&&user()['role']==='admin'){if(trim($_POST['reason']??'')==='')$error='دلیل ارجاع الزامی است.';else{db()->prepare('INSERT INTO referrals(student_id,counselor_id,created_by,subject,reason,priority,next_followup_date) VALUES(?,?,?,?,?,?,?)')->execute([(int)$_POST['student_id'],(int)$_POST['counselor_id'],user()['id'],trim($_POST['subject']),trim($_POST['reason']),$_POST['priority']??'normal',($_POST['next_followup_date']??'')?:null]);$id=(int)db()->lastInsertId();audit('referral_created','referral',$id);flash('ارجاع با موفقیت ثبت شد.');redirect('/admin/referrals.php');}}elseif($action==='update'){db()->prepare('UPDATE referrals SET status=?,counselor_note=?,next_followup_date=? WHERE id=? AND (counselor_id=? OR ?=1)')->execute([$_POST['status'],trim($_POST['counselor_note']??''),($_POST['next_followup_date']??'')?:null,$id,user()['id'],user()['role']==='admin'?1:0]);audit('referral_updated','referral',$id);flash('وضعیت ارجاع ذخیره شد.');redirect('/admin/referrals.php');}}
$students=db()->query("SELECT id,name FROM users WHERE role='student' ORDER BY name")->fetchAll();$counselors=db()->query("SELECT id,name FROM users WHERE role='counselor' ORDER BY name")->fetchAll();if(user()['role']==='counselor'){$q=db()->prepare('SELECT r.*,s.name student_name FROM referrals r JOIN users s ON s.id=r.student_id WHERE r.counselor_id=? ORDER BY r.created_at DESC');$q->execute([user()['id']]);}else{$q=db()->query('SELECT r.*,s.name student_name,c.name counselor_name FROM referrals r JOIN users s ON s.id=r.student_id JOIN users c ON c.id=r.counselor_id ORDER BY r.created_at DESC');}$refs=$q;layout_start('ارجاع‌های مشاوره');?><div class="page-head"><div><p class="eyebrow">نسخه ۲.۳</p><h1>ارجاع‌های مشاوره</h1></div><a class="button secondary" href="<?=e(url('/admin/index.php'))?>">بازگشت</a></div><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><?php if(user()['role']==='admin'):?><div class="card"><h2>ارجاع جدید</h2><form class="form-grid" method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="create"><label>دانش‌آموز<select name="student_id" required><?php foreach($students as $x):?><option value="<?=$x['id']?>"><?=e($x['name'])?></option><?php endforeach;?></select></label><label>مشاور<select name="counselor_id" required><?php foreach($counselors as $x):?><option value="<?=$x['id']?>"><?=e($x['name'])?></option><?php endforeach;?></select></label><label>موضوع<input name="subject" required></label><label>اولویت<select name="priority"><option value="normal">عادی</option><option value="important">مهم</option><option value="urgent">فوری</option></select></label><label class="full">دلیل ارجاع<textarea name="reason" required></textarea></label><label>تاریخ پیگیری<input type="date" name="next_followup_date"></label><button class="button">ثبت ارجاع</button></form></div><?php endif;?><div class="card table-wrap"><table><thead><tr><th>دانش‌آموز</th><th>مشاور</th><th>موضوع</th><th>اولویت</th><th>وضعیت</th><th>یادداشت مشاور</th></tr></thead><tbody><?php while($r=$refs->fetch()):?><tr><td><?=e($r['student_name'])?></td><td><?=e($r['counselor_name']??'شما')?></td><td><?=e($r['subject'])?></td><td><?=e($r['priority'])?></td><td><form class="inline" method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="update"><input type="hidden" name="id" value="<?=$r['id']?>"><select name="status"><option value="new">جدید</option><option value="seen" <?=$r['status']==='seen'?'selected':''?>>مشاهده‌شده</option><option value="scheduled" <?=$r['status']==='scheduled'?'selected':''?>>جلسه تعیین شد</option><option value="in_progress" <?=$r['status']==='in_progress'?'selected':''?>>در حال پیگیری</option><option value="closed" <?=$r['status']==='closed'?'selected':''?>>بسته‌شده</option></select><button>ذخیره</button></form></td><td><?=e($r['counselor_note']??'—')?></td></tr><?php endwhile;?></tbody></table></div><?php layout_end(); ?>
